data: {"type":"response.output_text.done","content_index":0,"item_id":"msg_04626c52150deff5016aecc2f7bf3c87d2929f5461306c44c1","logprobs":[],"output_index":0,"sequence_number":815,"text":"<title>Café order</title>\n<meta name=\"idea\" content=\"Build a coffee order with quick menu browsing and a live total\">\n<nav aria-label=\"Main navigation\">\n  <a href=\"#menu\">Menu</a> · <button data-action=\"@orders: Recent orders screen for a coffee shop app\">Orders</button> · <button data-action=\"@profile: Customer profile screen for a coffee shop app\">Profile</button>\n</nav>\n<main id=\"menu\">\n  <h1>Good morning ☕</h1>\n  <p>What can we make for you?</p>\n  <label for=\"search\">Find a drink</label>\n  <input id=\"search\" type=\"search\" placeholder=\"Search coffee or tea\">\n  <label for=\"category\">Category</label>\n  <select id=\"category\"><option>All drinks</option><option>Espresso</option><option>Tea</option></select>\n  <section>\n    <h2>Popular</h2>\n    <article data-category=\"Espresso\">\n      <h3>Caramel latte</h3><p>Espresso, steamed milk, caramel · $5.25</p>\n      <button data-action=\"@caramel-latte: Details and customization for a caramel latte at a coffee shop\">Details</button>\n      <label>Qty <input class=\"qty\" type=\"number\" min=\"0\" value=\"0\" data-price=\"5.25\"></label>\n    </article>\n    <article data-category=\"Espresso\">\n      <h3>Cold brew</h3><p>Slow-steeped, smooth and refreshing · $4.50</p>\n      <button data-action=\"@cold-brew: Details and customization for cold brew at a coffee shop\">Details</button>\n      <label>Qty <input class=\"qty\" type=\"number\" min=\"0\" value=\"0\" data-price=\"4.50\"></label>\n    </article>\n    <article data-category=\"Tea\">\n      <h3>Matcha latte</h3><p>Stone-ground matcha with milk · $5.00</p>\n      <button data-action=\"@matcha-latte: Details and customization for a matcha latte at a coffee shop\">Details</button>\n      <label>Qty <input class=\"qty\" type=\"number\" min=\"0\" value=\"0\" data-price=\"5.00\"></label>\n    </article>\n  </section>\n  <article>\n    <h2>Your order</h2>\n    <p><span id=\"count\">0</span> drinks · <strong id=\"total\">$0.00</strong></p>\n    <button id=\"checkout\" data-action=\"@order-checkout: Checkout screen for a coffee shop order\">Checkout</button>\n  </article>\n</main>\n<script>\nconst items=[...document.querySelectorAll('article[data-category]')], search=document.querySelector('#search'), category=document.querySelector('#category');\nfunction update(){\n  const term=search.value.toLowerCase();\n  items.forEach(item=>item.hidden=!(item.textContent.toLowerCase().includes(term)&&(category.value==='All drinks'||item.dataset.category===category.value)));\n  const qty=[...document.querySelectorAll('.qty')].reduce((s,i)=>s+(+i.value||0),0);\n  const total=[...document.querySelectorAll('.qty')].reduce((s,i)=>s+(+i.value||0)*(+i.dataset.price),0);\n  document.querySelector('#count').textContent=qty.toLocaleString();\n  document.querySelector('#total').textContent='$'+total.toFixed(2);\n  document.querySelector('#checkout').disabled=!qty;\n}\nsearch.addEventListener('input',update); category.addEventListener('change',update);\ndocument.querySelectorAll('.qty').forEach(i=>i.addEventListener('input',update)); update();\n</script>"}

